"use client";import { useEffect,useState } from "react";export function Newsletter(){const [email,setEmail]=useState(""),[list,setList]=useState<string[]>([]),[message,setMessage]=useState("");useEffect(()=>setList(JSON.parse(localStorage.getItem("matsuri-newsletter")||"[]") as string[]),[]);function save(next:string[]){localStorage.setItem("matsuri-newsletter",JSON.stringify(next));setList(next)}function subscribe(e:React.FormEvent){e.preventDefault();const x=email.trim().toLowerCase();if(!x)return;if(list.includes(x)){setMessage("That email is already subscribed.");return}save([...list,x]);setMessage("Thanks — you are subscribed.")}return <div className="form"><form className="search" onSubmit={subscribe}><label className="field">EMAIL<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><button className="button">Subscribe</button></form>{message&&<p className="notice">{message}</p>}<section><h2>Current subscription status</h2>{list.length?<ul>{list.map(x=><li key={x}>{x} <button className="button alt" onClick={()=>{save(list.filter(y=>y!==x));setMessage("Subscription removed.")}}>Unsubscribe</button></li>)}</ul>:<p className="muted">No newsletter email is stored in this browser.</p>}</section></div>}
